import { useEffect, useMemo, useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { Loader2, Plus, Save, Trash2 } from "lucide-react";

import { api } from "@/lib/api";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { formatCAD, isoDate, isoMonth } from "@/lib/utils";
import type { ExpenseEntry, ExpensesFile } from "@/lib/types";

const CATEGORIES = [
  "rent",
  "utilities",
  "payroll",
  "supplies",
  "maintenance",
  "insurance",
  "tax",
  "fees",
  "marketing",
  "other",
];

export default function ExpensesPage() {
  const qc = useQueryClient();
  const [month, setMonth] = useState(isoMonth());
  const [file, setFile] = useState<ExpensesFile>({ month, entries: [] });
  const [saving, setSaving] = useState(false);

  const q = useQuery({
    queryKey: ["expenses", month],
    queryFn: () => api.readData<ExpensesFile>(`expenses/${month}.json`),
  });

  useEffect(() => {
    if (q.data?.exists && q.data.data) setFile(q.data.data);
    else setFile({ month, entries: [] });
  }, [month, q.data?.exists, q.data?.data]);

  const total = useMemo(
    () => file.entries.reduce((s, e) => s + (e.amountCAD || 0), 0),
    [file.entries],
  );

  function update(id: string, patch: Partial<ExpenseEntry>) {
    setFile((f) => ({
      ...f,
      entries: f.entries.map((e) => (e.id === id ? { ...e, ...patch } : e)),
    }));
  }

  function addEntry() {
    setFile((f) => ({
      ...f,
      entries: [
        ...f.entries,
        {
          id: crypto.randomUUID(),
          date: isoDate(),
          category: "supplies",
          vendor: "",
          amountCAD: 0,
        },
      ],
    }));
  }

  function remove(id: string) {
    setFile((f) => ({ ...f, entries: f.entries.filter((e) => e.id !== id) }));
  }

  async function save() {
    setSaving(true);
    try {
      await api.writeData(
        `expenses/${month}.json`,
        { ...file, month },
        q.data?.sha ?? null,
        `expenses for ${month}`,
      );
      toast.success("Expenses saved");
      qc.invalidateQueries({ queryKey: ["expenses"] });
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed to save");
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="space-y-6">
      <header className="flex flex-wrap items-end justify-between gap-4">
        <div>
          <h1 className="text-3xl font-semibold tracking-tight">Expenses</h1>
          <p className="text-sm text-muted-foreground">Capture monthly recurring + one-off costs.</p>
        </div>
        <div className="flex items-center gap-2">
          <Label className="text-xs text-muted-foreground">Month</Label>
          <Input
            type="month"
            value={month}
            onChange={(e) => setMonth(e.target.value)}
            className="w-44"
          />
        </div>
      </header>

      <Card>
        <CardHeader className="flex flex-row items-center justify-between">
          <div>
            <CardTitle>Entries</CardTitle>
            <CardDescription>
              Total this month: <strong>{formatCAD(total)}</strong>
            </CardDescription>
          </div>
          <Button onClick={addEntry} variant="outline">
            <Plus className="h-4 w-4" /> Add expense
          </Button>
        </CardHeader>
        <CardContent className="space-y-3">
          {q.isLoading ? (
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <Loader2 className="h-4 w-4 animate-spin" /> Loading…
            </div>
          ) : null}
          {file.entries.length === 0 ? (
            <div className="rounded-md border border-dashed py-10 text-center text-sm text-muted-foreground">
              No expenses yet for {month}.
            </div>
          ) : null}
          {file.entries.map((e) => (
            <div
              key={e.id}
              className="grid grid-cols-2 gap-3 rounded-md border bg-card/40 p-3 md:grid-cols-[1fr_1.2fr_1.5fr_1fr_2fr_auto] md:items-end"
            >
              <div className="space-y-1.5">
                <Label className="text-xs text-muted-foreground">Date</Label>
                <Input
                  type="date"
                  value={e.date}
                  onChange={(ev) => update(e.id, { date: ev.target.value })}
                />
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs text-muted-foreground">Category</Label>
                <Select value={e.category} onValueChange={(v) => update(e.id, { category: v })}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {CATEGORIES.map((c) => (
                      <SelectItem key={c} value={c}>
                        {c}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs text-muted-foreground">Vendor</Label>
                <Input
                  value={e.vendor}
                  onChange={(ev) => update(e.id, { vendor: ev.target.value })}
                  placeholder="Hydro One"
                />
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs text-muted-foreground">Amount $</Label>
                <Input
                  type="number"
                  step="0.01"
                  value={e.amountCAD || ""}
                  onChange={(ev) => update(e.id, { amountCAD: parseFloat(ev.target.value) || 0 })}
                />
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs text-muted-foreground">Notes</Label>
                <Input
                  value={e.notes ?? ""}
                  onChange={(ev) => update(e.id, { notes: ev.target.value })}
                  placeholder="Optional"
                />
              </div>
              <Button
                variant="ghost"
                size="icon"
                onClick={() => remove(e.id)}
                aria-label="Remove"
              >
                <Trash2 className="h-4 w-4" />
              </Button>
            </div>
          ))}
        </CardContent>
      </Card>

      <div className="flex justify-end">
        <Button size="lg" onClick={save} disabled={saving}>
          {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
          Save expenses
        </Button>
      </div>
    </div>
  );
}
