/**
 * Offline-safe write queue.
 *
 * Gas-station wifi drops mid-submit and an EOD report is real money, so a write
 * that never reached the server is parked here and replayed when the connection
 * comes back. This module is deliberately pure: storage and the send function
 * are injected, so it is unit-testable without a DOM or a network.
 *
 * The single most important invariant: ONLY a genuine network failure
 * (ApiError.status === 0) may enqueue. A 401/403/409/5xx is the server saying
 * "no" — replaying it later would corrupt data. That branch lives in api.ts.
 */

export interface QueuedWrite {
  id: string;
  path: string;
  data: unknown;
  expectedSha: string | null;
  message?: string;
  queuedAt: string;
  /** Set when the replay hit a 409 sha conflict. Never auto-retried. */
  conflict?: true;
  /** Last non-conflict replay failure, kept for the banner / debugging. */
  lastError?: string;
}

/** The slice of `Storage` we use — lets tests inject a Map-backed fake. */
export interface StorageLike {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

export const QUEUE_KEY = "mkrgas.offline-queue";

/**
 * localStorage is ~5MB per origin and receipt photos ride along as base64, so a
 * couple of queued EOD reports can realistically approach the cap. Refuse the
 * enqueue before we blow it rather than let setItem throw and lose the write.
 * ponytail: string length ~= bytes here (JSON of base64/ASCII); if payloads ever
 * carry real unicode, swap in TextEncoder().encode(s).length.
 */
export const MAX_QUEUE_BYTES = 4_000_000;

export class QueueFullError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "QueueFullError";
  }
}

let listeners: Array<() => void> = [];

/** Notified on every queue mutation so the banner can re-render. */
export function subscribeQueue(fn: () => void): () => void {
  listeners.push(fn);
  return () => {
    listeners = listeners.filter((l) => l !== fn);
  };
}

function notify() {
  for (const fn of listeners) fn();
}

export function readQueue(store: StorageLike): QueuedWrite[] {
  const raw = store.getItem(QUEUE_KEY);
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? (parsed as QueuedWrite[]) : [];
  } catch {
    // Corrupt entry: treat as empty rather than wedging every future write.
    return [];
  }
}

function persist(store: StorageLike, items: QueuedWrite[]) {
  if (items.length === 0) store.removeItem(QUEUE_KEY);
  else store.setItem(QUEUE_KEY, JSON.stringify(items));
  notify();
}

export function clearQueue(store: StorageLike) {
  persist(store, []);
}

export function queueStatus(store: StorageLike): { pending: number; conflict: boolean } {
  const items = readQueue(store);
  return { pending: items.length, conflict: items.some((i) => i.conflict) };
}

export function enqueue(
  store: StorageLike,
  item: Pick<QueuedWrite, "path" | "data" | "expectedSha" | "message">,
): QueuedWrite {
  const queued: QueuedWrite = {
    id:
      typeof crypto !== "undefined" && crypto.randomUUID
        ? crypto.randomUUID()
        : `q_${Date.now()}_${Math.random().toString(36).slice(2)}`,
    path: item.path,
    data: item.data,
    expectedSha: item.expectedSha,
    message: item.message,
    queuedAt: new Date().toISOString(),
  };
  const next = [...readQueue(store), queued];
  const serialized = JSON.stringify(next);
  if (serialized.length > MAX_QUEUE_BYTES) {
    throw new QueueFullError(
      "Offline storage is full, so this save could not be kept on the device. " +
        "Reconnect and save again — do not close this page, or the entry will be lost. " +
        "Removing the receipt photo will make it small enough to queue.",
    );
  }
  try {
    store.setItem(QUEUE_KEY, serialized);
  } catch (e) {
    // Quota exceeded despite our own guard (other keys share the origin budget).
    throw new QueueFullError(
      `Offline storage is full, so this save could not be kept on the device (${
        e instanceof Error ? e.message : "storage error"
      }). Reconnect and save again.`,
    );
  }
  notify();
  return queued;
}

export interface DrainResult {
  sent: number;
  conflicts: number;
  remaining: number;
  /** True when we gave up early because the network is still down. */
  stopped: boolean;
}

export type SendWrite = (item: QueuedWrite) => Promise<unknown>;

function statusOf(err: unknown): number | undefined {
  const s = (err as { status?: unknown } | null)?.status;
  return typeof s === "number" ? s : undefined;
}

let inFlight: Promise<DrainResult> | null = null;

/**
 * Replay queued writes FIFO.
 *
 * - success  -> drop the item
 * - 409      -> mark `conflict` and leave it; the server has newer data and
 *               blindly re-PUTting would clobber it. Surfaced to the user.
 * - status 0 -> still offline; stop the whole drain and keep everything.
 * - other    -> record the error, keep the item, move on (retried next drain).
 *
 * Re-entrant callers share one pass. Mount and the `online` event both trigger a
 * drain (and StrictMode double-fires the mount one), so two overlapping passes
 * would send the same item twice — the duplicate PUT carries the now-stale
 * expectedSha, earns a 409, and tells the user to re-enter an EOD report that
 * actually saved. Exactly the outcome this queue exists to prevent.
 * ponytail: one global latch — there is one queue behind one localStorage key;
 * key it by store if a second queue ever exists.
 */
export function drain(store: StorageLike, send: SendWrite): Promise<DrainResult> {
  if (inFlight) return inFlight;
  inFlight = drainOnce(store, send).finally(() => {
    inFlight = null;
  });
  return inFlight;
}

async function drainOnce(store: StorageLike, send: SendWrite): Promise<DrainResult> {
  const start = readQueue(store);
  const flags = new Map<string, Partial<QueuedWrite>>();
  let sent = 0;
  let stopped = false;

  // Persist after every item: a tab closed mid-drain must not re-send a write
  // that already landed. Re-reads first so writes enqueued while we awaited
  // survive, and re-applies accumulated flags so they are never lost.
  const commit = (removeId?: string) => {
    persist(
      store,
      readQueue(store)
        .filter((i) => i.id !== removeId)
        .map((i) => (flags.has(i.id) ? { ...i, ...flags.get(i.id) } : i)),
    );
  };

  for (const item of start) {
    if (item.conflict) continue;
    try {
      await send(item);
      sent += 1;
      commit(item.id);
    } catch (err) {
      const status = statusOf(err);
      const message = err instanceof Error ? err.message : String(err);
      if (status === 0) {
        stopped = true;
        break;
      }
      flags.set(
        item.id,
        status === 409 ? { conflict: true, lastError: message } : { lastError: message },
      );
      commit();
    }
  }

  const remaining = readQueue(store);
  return {
    sent,
    conflicts: remaining.filter((i) => i.conflict).length,
    remaining: remaining.length,
    stopped,
  };
}

/** Real localStorage, or null when there is no DOM (SSR / node tests). */
export function browserStore(): StorageLike | null {
  try {
    if (typeof localStorage === "undefined") return null;
    return localStorage;
  } catch {
    return null;
  }
}
