import { totalCashCount } from "@/components/CashDrawer";
import type { SalesFile } from "@/lib/types";

/**
 * Drawer over/short for a day, in CAD. Positive = more cash than the sales
 * say there should be (over), negative = missing (short).
 *
 *   expected drawer = revenue - card tenders - bank deposit - float kept
 *   variance        = counted - expected
 *
 * Returns null when the day has no counted drawer — an uncounted day is
 * unknown, not zero, and averaging zeros would hide real shrink.
 */
export function cashVariance(s: SalesFile): number | null {
  if (!s.cashCount) return null;
  const revenue =
    s.fuel.reduce((a, f) => a + (f.bullochSalesCAD || 0), 0) +
    s.store.generalCAD +
    s.store.tobaccoCAD +
    s.store.alcoholCAD +
    s.store.otherCAD +
    (s.store.lotteryInCAD - s.store.lotteryOutCAD);
  const expected =
    revenue - (s.card.debitCAD + s.card.creditCAD) - s.bankDepositCAD - s.cashFloatCAD;
  return totalCashCount(s.cashCount) - expected;
}
