/**
 * Lightweight linear-regression forecast with a confidence band.
 *
 * Designed for short-horizon projections (e.g. next 30 days of gross
 * profit) where seasonal effects can be ignored. Pure function, easily
 * unit-tested without React.
 */

export interface ForecastPoint {
  x: number;        // day index from 0
  forecast: number; // fitted value
  lower: number;    // forecast - z * SE
  upper: number;    // forecast + z * SE
}

export interface ForecastResult {
  /** Past series fitted with the linear model (same length as input.values). */
  fitted: number[];
  /** Confidence band for the future horizon. */
  future: ForecastPoint[];
  slope: number;
  intercept: number;
  /** Residual standard error of the regression. */
  se: number;
  /** Coefficient of determination R^2 in [0, 1]. */
  r2: number;
}

export interface ForecastInput {
  values: Array<number | null | undefined>;
  /** Number of future periods to forecast. */
  horizon: number;
  /** Confidence multiplier on SE. 1.0 ~ 68%, 1.96 ~ 95%. Defaults to 1.96. */
  z?: number;
  /** Whether to clip the forecast (and band) at zero. Useful for revenue-like series. */
  clipNonNegative?: boolean;
}

/**
 * Computes the linear-regression forecast for a numeric time series.
 *
 * Missing values (null/undefined/NaN) are skipped in the fit. The resulting
 * "future" array starts one step past the last observation.
 */
export function linearForecast(input: ForecastInput): ForecastResult {
  const z = input.z ?? 1.96;
  const pairs: Array<[number, number]> = [];
  input.values.forEach((v, i) => {
    if (v == null || !Number.isFinite(v)) return;
    pairs.push([i, v as number]);
  });

  if (pairs.length < 2) {
    return {
      fitted: input.values.map(() => 0),
      future: Array.from({ length: input.horizon }, (_, i) => ({
        x: input.values.length + i,
        forecast: 0,
        lower: 0,
        upper: 0,
      })),
      slope: 0,
      intercept: 0,
      se: 0,
      r2: 0,
    };
  }

  const n = pairs.length;
  let sumX = 0;
  let sumY = 0;
  let sumXX = 0;
  let sumXY = 0;
  for (const [x, y] of pairs) {
    sumX += x;
    sumY += y;
    sumXX += x * x;
    sumXY += x * y;
  }
  const meanX = sumX / n;
  const meanY = sumY / n;
  const denom = sumXX - sumX * sumX / n;
  const slope = denom === 0 ? 0 : (sumXY - sumX * sumY / n) / denom;
  const intercept = meanY - slope * meanX;

  let ssRes = 0;
  let ssTot = 0;
  for (const [x, y] of pairs) {
    const yhat = intercept + slope * x;
    ssRes += (y - yhat) ** 2;
    ssTot += (y - meanY) ** 2;
  }
  const r2 = ssTot === 0 ? 0 : 1 - ssRes / ssTot;
  const se = n > 2 ? Math.sqrt(ssRes / (n - 2)) : 0;

  const fitted = input.values.map((_, i) => {
    const y = intercept + slope * i;
    return input.clipNonNegative ? Math.max(0, y) : y;
  });

  const future: ForecastPoint[] = [];
  for (let h = 1; h <= input.horizon; h++) {
    const i = input.values.length - 1 + h;
    const yhat = intercept + slope * i;
    const lower = yhat - z * se;
    const upper = yhat + z * se;
    future.push({
      x: i,
      forecast: input.clipNonNegative ? Math.max(0, yhat) : yhat,
      lower: input.clipNonNegative ? Math.max(0, lower) : lower,
      upper: input.clipNonNegative ? Math.max(0, upper) : upper,
    });
  }

  return { fitted, future, slope, intercept, se, r2 };
}

/**
 * Convenience helper: given an array of {date, value} pairs and a horizon,
 * returns labels + forecast arrays ready to feed into an ECharts line chart.
 */
export function projectForecast(
  past: Array<{ date: string; value: number | null | undefined }>,
  horizon: number,
  opts: { clipNonNegative?: boolean; z?: number } = {},
): {
  labels: string[];
  actual: Array<number | null>;
  fitted: Array<number | null>;
  forecast: Array<number | null>;
  lower: Array<number | null>;
  upper: Array<number | null>;
  result: ForecastResult;
} {
  const result = linearForecast({
    values: past.map((p) => p.value ?? null),
    horizon,
    z: opts.z,
    clipNonNegative: opts.clipNonNegative,
  });

  const futureDates: string[] = [];
  if (past.length > 0) {
    const last = new Date(`${past[past.length - 1].date}T00:00:00Z`);
    for (let h = 1; h <= horizon; h++) {
      const d = new Date(last.getTime() + h * 86_400_000);
      futureDates.push(d.toISOString().slice(0, 10));
    }
  }

  const labels = [...past.map((p) => p.date), ...futureDates];
  const actual: Array<number | null> = [
    ...past.map((p) => (p.value == null ? null : Number(p.value))),
    ...futureDates.map(() => null),
  ];
  const fitted: Array<number | null> = [
    ...result.fitted.map((v) => Number(v.toFixed(4))),
    ...futureDates.map(() => null),
  ];
  const forecast: Array<number | null> = [
    ...past.map(() => null),
    ...result.future.map((p) => Number(p.forecast.toFixed(4))),
  ];
  const lower: Array<number | null> = [
    ...past.map(() => null),
    ...result.future.map((p) => Number(p.lower.toFixed(4))),
  ];
  const upper: Array<number | null> = [
    ...past.map(() => null),
    ...result.future.map((p) => Number(p.upper.toFixed(4))),
  ];
  return { labels, actual, fitted, forecast, lower, upper, result };
}
