/**
 * Employee operations dashboard — everything a cashier needs for the shift,
 * nothing about profit. Reads only employee-permitted paths: today's sales
 * (revenue/volume), pump prices, and the week's schedule. Margin, expenses,
 * and the AI brief are owner-only and never requested from here.
 */
import { useMemo } from "react";
import { Link } from "react-router-dom";
import { useQueries, useQuery } from "@tanstack/react-query";
import {
  AlertTriangle,
  ArrowRight,
  BarChart3,
  Calendar,
  ClipboardList,
  Droplets,
  Fuel,
  Gauge,
  ShoppingBag,
  Ticket,
  Truck,
} from "lucide-react";

import { api } from "@/lib/api";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { AnimatedNumber } from "@/components/AnimatedNumber";
import { Sparkline } from "@/charts/Sparkline";
import { colorForGrade } from "@/charts/theme";
import { useAuth } from "@/lib/auth-store";
import { formatCAD, formatLiters, isoDate, isoWeek } from "@/lib/utils";
import type { FuelGradesConfig, GasPricesFile, SalesFile, SchedulesFile } from "@/lib/types";

function lastNDates(n: number): string[] {
  const out: string[] = [];
  const now = new Date();
  for (let i = n - 1; i >= 0; i--) {
    const d = new Date(now);
    d.setDate(now.getDate() - i);
    out.push(isoDate(d));
  }
  return out;
}

export default function EmployeeDashboard() {
  const user = useAuth((s) => s.user)!;
  const today = isoDate();
  const week = isoWeek();
  const trendDates = useMemo(() => lastNDates(14), []);

  const gradesQ = useQuery({
    queryKey: ["config", "fuel_grades"],
    queryFn: () => api.readData<FuelGradesConfig>("config/fuel_grades.json"),
  });
  const pricesQ = useQuery({
    queryKey: ["gas_prices", today],
    queryFn: () => api.readData<GasPricesFile>(`gas_prices/${today}.json`),
  });
  const todaySalesQ = useQuery({
    queryKey: ["sales", today],
    queryFn: () => api.readData<SalesFile>(`sales/${today}.json`),
  });
  const scheduleQ = useQuery({
    queryKey: ["schedule", week],
    queryFn: () => api.readData<SchedulesFile>(`schedules/${week}.json`),
  });
  const trendQs = useQueries({
    queries: trendDates.map((d) => ({
      queryKey: ["sales", d],
      queryFn: () => api.readData<SalesFile>(`sales/${d}.json`),
    })),
  });

  const grades = gradesQ.data?.data?.grades ?? [];
  const prices = pricesQ.data?.exists ? pricesQ.data.data : undefined;
  const sales = todaySalesQ.data?.exists ? todaySalesQ.data.data : undefined;

  const fuelRevenue = sales?.fuel.reduce((s, f) => s + (f.bullochSalesCAD || 0), 0) ?? 0;
  const fuelLiters = sales?.fuel.reduce((s, f) => s + (f.bullochVolumeL || 0), 0) ?? 0;
  const storeRevenue = sales
    ? sales.store.generalCAD + sales.store.tobaccoCAD + sales.store.alcoholCAD + sales.store.otherCAD
    : 0;
  const lotteryNet = sales ? sales.store.lotteryInCAD - sales.store.lotteryOutCAD : 0;

  const sparkRevenue = trendQs.map((q) => {
    const d = q.data?.exists ? q.data.data : undefined;
    return d ? d.fuel.reduce((s, f) => s + (f.bullochSalesCAD || 0), 0) : 0;
  });
  const sparkLiters = trendQs.map((q) => {
    const d = q.data?.exists ? q.data.data : undefined;
    return d ? d.fuel.reduce((s, f) => s + (f.bullochVolumeL || 0), 0) : 0;
  });

  // Tank levels from the EOD inventory recorded in sales/ (employees can read
  // that; derived/margin is owner-only). Whoever is on shift should be the
  // first to know a tank is running low.
  const trendSales = trendQs.map((q) => (q.data?.exists ? q.data.data : undefined));
  const tanks = grades.map((g) => {
    let currentL = 0;
    for (let i = trendSales.length - 1; i >= 0; i--) {
      const row = trendSales[i]?.fuel.find((f) => f.gradeId === g.id);
      if (row?.eodInventoryL != null) {
        currentL = row.eodInventoryL;
        break;
      }
    }
    const capacity = g.tankCapacityL ?? 0;
    const pctFull = capacity > 0 ? Math.min(100, Math.max(0, (currentL / capacity) * 100)) : 0;
    const vols = trendSales
      .map((d) => d?.fuel.find((f) => f.gradeId === g.id)?.bullochVolumeL ?? 0)
      .filter((v) => v > 0);
    const avgDaily = vols.length ? vols.reduce((s, v) => s + v, 0) / vols.length : 0;
    const daysLeft = avgDaily > 0 && currentL > 0 ? currentL / avgDaily : null;
    return { g, currentL, capacity, pctFull, daysLeft };
  });
  const lowTanks = tanks.filter((t) => t.capacity > 0 && t.pctFull < 20);

  const myShifts = (scheduleQ.data?.exists ? scheduleQ.data.data?.shifts ?? [] : [])
    .filter((s) => s.employeeName.toLowerCase() === user.displayName.toLowerCase() || s.employeeId === user.sub)
    .sort((a, b) => (a.date + a.startTime).localeCompare(b.date + b.startTime));

  return (
    <div className="space-y-8">
      <header>
        <div className="text-sm text-muted-foreground">
          {new Date().toLocaleDateString("en-CA", {
            weekday: "long",
            year: "numeric",
            month: "long",
            day: "numeric",
          })}
        </div>
        <h1 className="text-3xl font-semibold tracking-tight">
          Good to see you, {user.displayName.split(" ")[0]}
        </h1>
        <p className="text-sm text-muted-foreground">Your shift hub — prices, entries, schedule.</p>
      </header>

      {lowTanks.length > 0 ? (
        <div className="animate-fade-in flex items-start gap-3 rounded-xl border border-amber-400/40 bg-amber-50/40 p-4 text-sm dark:bg-amber-950/20">
          <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0 text-amber-600 dark:text-amber-400" />
          <div>
            <div className="font-medium text-amber-700 dark:text-amber-300">
              Low fuel — tell the owner to order
            </div>
            <p className="text-muted-foreground">
              {lowTanks
                .map(
                  (t) =>
                    `${t.g.label} ${t.pctFull.toFixed(0)}%${t.daysLeft != null ? ` (~${t.daysLeft.toFixed(1)}d left)` : ""}`,
                )
                .join(" · ")}
            </p>
          </div>
        </div>
      ) : null}

      {/* Quick actions */}
      <section className="grid gap-4 sm:grid-cols-3">
        <ActionCard
          to="/eod"
          icon={<ClipboardList className="h-5 w-5" />}
          title="Enter end-of-day"
          desc={sales?.submittedAt ? "Today's report is in — update it anytime." : "Not submitted yet for today."}
          highlight={!sales?.submittedAt}
          index={0}
        />
        <ActionCard
          to="/fuel"
          icon={<Fuel className="h-5 w-5" />}
          title="Update pump prices"
          desc={prices ? "Prices set for today." : "No prices recorded today."}
          highlight={!prices}
          index={1}
        />
        <ActionCard
          to="/fuel/delivery"
          icon={<Truck className="h-5 w-5" />}
          title="Record a delivery"
          desc="Log an invoice when the tanker arrives."
          index={2}
        />
      </section>

      {/* Today at the store */}
      <section className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">
        <StatCard
          icon={<BarChart3 className="h-4 w-4" />}
          label="Fuel revenue today"
          value={fuelRevenue}
          format={formatCAD}
          spark={<Sparkline data={sparkRevenue} color="#14b8a6" />}
          index={0}
        />
        <StatCard
          icon={<Droplets className="h-4 w-4" />}
          label="Liters pumped today"
          value={fuelLiters}
          format={formatLiters}
          spark={<Sparkline data={sparkLiters} color="#38bdf8" />}
          index={1}
        />
        <StatCard
          icon={<ShoppingBag className="h-4 w-4" />}
          label="Store sales today"
          value={storeRevenue}
          format={formatCAD}
          index={2}
        />
        <StatCard
          icon={<Ticket className="h-4 w-4" />}
          label="Lottery net today"
          value={lotteryNet}
          format={formatCAD}
          index={3}
        />
      </section>

      <section className="grid gap-4 lg:grid-cols-2">
        {/* Pump price board */}
        <Card className="animate-fade-in">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Fuel className="h-4 w-4 text-primary" /> Today's pump prices
            </CardTitle>
            <CardDescription>
              {prices?.setBy ? `Set by ${prices.setBy}` : "Set them from the Fuel page when they change."}
            </CardDescription>
          </CardHeader>
          <CardContent>
            {grades.length === 0 ? (
              <p className="text-sm text-muted-foreground">No fuel grades configured.</p>
            ) : (
              <div className="grid grid-cols-2 gap-3 sm:grid-cols-3">
                {grades.map((g) => {
                  const p = prices?.prices.find((x) => x.gradeId === g.id);
                  return (
                    <div
                      key={g.id}
                      className="rounded-lg border border-border/60 bg-background/30 p-3 text-center"
                      style={{ boxShadow: `inset 0 2px 0 0 ${colorForGrade(g.id)}55` }}
                    >
                      <div className="text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
                        {g.label}
                      </div>
                      <div className="number-tabular mt-1 text-xl font-semibold">
                        {p ? `${(p.pumpPricePerL * 100).toFixed(1)}¢` : "—"}
                      </div>
                      <div className="text-[10px] text-muted-foreground">per liter</div>
                    </div>
                  );
                })}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Tank levels */}
        <Card className="animate-fade-in lg:col-span-2">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Gauge className="h-4 w-4 text-primary" /> Tank levels
            </CardTitle>
            <CardDescription>
              From the last recorded end-of-day inventory. Keep it filled in and this stays accurate.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-3">
            {tanks.length === 0 ? (
              <p className="text-sm text-muted-foreground">No fuel grades configured.</p>
            ) : (
              tanks.map((t) => (
                <div key={t.g.id} className="space-y-1.5">
                  <div className="flex items-baseline justify-between text-sm">
                    <span className="font-medium">{t.g.label}</span>
                    <span className="number-tabular text-muted-foreground">
                      {t.capacity > 0 ? `${t.pctFull.toFixed(0)}% · ` : ""}
                      {formatLiters(t.currentL)}
                      {t.daysLeft != null ? ` · ~${t.daysLeft.toFixed(1)}d left` : ""}
                    </span>
                  </div>
                  <div className="h-2.5 w-full overflow-hidden rounded-full bg-secondary">
                    <div
                      className={`h-full rounded-full transition-[width] duration-700 ease-out ${
                        t.pctFull < 20 ? "bg-rose-500" : t.pctFull < 40 ? "bg-amber-500" : "bg-emerald-500"
                      }`}
                      style={{ width: `${t.capacity > 0 ? t.pctFull : 0}%` }}
                    />
                  </div>
                </div>
              ))
            )}
          </CardContent>
        </Card>

        {/* My shifts this week */}
        <Card className="animate-fade-in" style={{ animationDelay: "80ms", animationFillMode: "backwards" }}>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Calendar className="h-4 w-4 text-primary" /> My shifts — {week}
            </CardTitle>
            <CardDescription>
              <Link to="/schedule" className="inline-flex items-center gap-1 hover:text-foreground">
                Full schedule <ArrowRight className="h-3 w-3" />
              </Link>
            </CardDescription>
          </CardHeader>
          <CardContent>
            {myShifts.length === 0 ? (
              <p className="text-sm text-muted-foreground">No shifts assigned to you this week.</p>
            ) : (
              <ul className="space-y-2">
                {myShifts.map((s) => {
                  const isToday = s.date === today;
                  return (
                    <li
                      key={s.id}
                      className={`flex items-center justify-between rounded-lg border px-3 py-2 text-sm ${
                        isToday ? "border-primary/40 bg-primary/5" : "border-border/60 bg-background/30"
                      }`}
                    >
                      <span className="flex items-center gap-2">
                        {isToday ? <Badge className="px-1.5 py-0 text-[10px]">Today</Badge> : null}
                        {new Date(`${s.date}T00:00:00`).toLocaleDateString("en-CA", {
                          weekday: "short",
                          month: "short",
                          day: "numeric",
                        })}
                      </span>
                      <span className="number-tabular text-muted-foreground">
                        {s.startTime}–{s.endTime}
                      </span>
                    </li>
                  );
                })}
              </ul>
            )}
          </CardContent>
        </Card>
      </section>
    </div>
  );
}

function ActionCard({
  to,
  icon,
  title,
  desc,
  highlight,
  index = 0,
}: {
  to: string;
  icon: React.ReactNode;
  title: string;
  desc: string;
  highlight?: boolean;
  index?: number;
}) {
  return (
    <Link to={to} className="group block">
      <Card
        className={`animate-fade-in h-full ${highlight ? "border-primary/40" : ""}`}
        style={{ animationDelay: `${index * 70}ms`, animationFillMode: "backwards" }}
      >
        <CardContent className="flex items-start gap-3 p-5">
          <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-primary/10 text-primary ring-1 ring-inset ring-primary/15 transition-transform group-hover:scale-110">
            {icon}
          </span>
          <div className="min-w-0">
            <div className="flex items-center gap-1 font-medium">
              {title}
              <ArrowRight className="h-3.5 w-3.5 opacity-0 transition-all group-hover:translate-x-0.5 group-hover:opacity-100" />
            </div>
            <p className="mt-0.5 text-xs text-muted-foreground">{desc}</p>
          </div>
        </CardContent>
      </Card>
    </Link>
  );
}

function StatCard({
  icon,
  label,
  value,
  format,
  spark,
  index = 0,
}: {
  icon: React.ReactNode;
  label: string;
  value: number;
  format: (n: number) => string;
  spark?: React.ReactNode;
  index?: number;
}) {
  return (
    <Card
      className="animate-fade-in overflow-hidden"
      style={{ animationDelay: `${index * 70}ms`, animationFillMode: "backwards" }}
    >
      <CardContent className="space-y-2 p-5">
        <div className="flex items-center justify-between text-sm text-muted-foreground">
          <span>{label}</span>
          <span className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary/10 text-primary ring-1 ring-inset ring-primary/15">
            {icon}
          </span>
        </div>
        <AnimatedNumber
          value={value}
          format={format}
          className="number-tabular block text-2xl font-semibold tracking-tight"
        />
        {spark ? <div className="-mx-1 -mb-1">{spark}</div> : <div className="h-[2px]" />}
      </CardContent>
    </Card>
  );
}
