/**
 * Excel importer for the original "Margin Management by day" workbook.
 *
 * The user's existing spreadsheet has one sheet per fuel grade with these
 * columns (per the math engine in src/lib/math/cost.ts):
 *
 *   A: date (or row index)
 *   B: invoice #
 *   C: purchase L (delivery)
 *   D: end-of-day inventory L
 *   E: invoice unit price $/L (ex-tax)
 *   F: delivery cost $/L
 *   G: product cost incl delivery $/L (computed)
 *   H: rolling-avg cost $/L (computed)
 *   I: Bulloch sales $
 *   J: avg pump price $/L (computed)
 *   K: net sell price $/L (computed)
 *   L: associate margin $/L (computed)
 *   M: Bulloch volume L
 *   N: gross profit $ (computed)
 *
 * The importer is column-letter agnostic -- it inspects header text and
 * matches keywords so renamed/repositioned columns still work.
 */
import * as XLSX from "xlsx";

import type { FuelGrade } from "./types";

export interface ImportedDayRow {
  date: string; // ISO YYYY-MM-DD
  gradeId: string;
  bullochSalesCAD: number;
  bullochVolumeL: number;
  eodInventoryL?: number;
  purchaseL?: number;
  productCostExTaxPerL?: number;
  deliveryCostPerL?: number;
  invoiceNo?: string;
}

export interface ImportPreview {
  rows: ImportedDayRow[];
  sheetSummaries: Array<{
    sheetName: string;
    detectedGradeId: string | null;
    rowsParsed: number;
    rowsSkipped: number;
    firstDate?: string;
    lastDate?: string;
  }>;
  warnings: string[];
}

const HEADER_HINTS: Record<keyof ImportedDayRow | "_skip", RegExp[]> = {
  date: [/^date$/i, /^day$/i, /\bdate\b/i],
  gradeId: [],
  bullochSalesCAD: [/sales/i, /^\$?i$/i, /bulloch.*\$/i, /\brevenue\b/i],
  bullochVolumeL: [/volume/i, /liter/i, /litre/i, /^m$/i, /\bL\b/i, /sold/i],
  eodInventoryL: [/inv/i, /eod/i, /^d$/i, /end of day/i],
  purchaseL: [/purchase/i, /delivery.*L/i, /^c$/i, /received/i],
  productCostExTaxPerL: [/cost.*ex/i, /invoice.*price/i, /unit.*price/i, /^e$/i],
  deliveryCostPerL: [/delivery.*cost/i, /freight/i, /^f$/i],
  invoiceNo: [/invoice/i, /^b$/i, /\binv #/i, /\binv no\b/i],
  _skip: [],
};

function pickColumn(headers: string[], hints: RegExp[]): number {
  for (let i = 0; i < headers.length; i++) {
    const h = (headers[i] ?? "").toString().trim();
    if (!h) continue;
    if (hints.some((r) => r.test(h))) return i;
  }
  return -1;
}

function excelSerialToDate(serial: number): string {
  // Excel: days since 1900-01-01 with the 1900 leap-year bug. SheetJS already
  // returns Date objects when cell.t === "d", but raw numbers still appear in
  // some sheets. Use SSF-compatible offset.
  const utc = (serial - 25569) * 86400 * 1000;
  const d = new Date(utc);
  if (isNaN(d.getTime())) return "";
  return d.toISOString().slice(0, 10);
}

function toIso(v: unknown): string {
  if (!v) return "";
  if (v instanceof Date) return v.toISOString().slice(0, 10);
  if (typeof v === "number") return excelSerialToDate(v);
  const s = String(v).trim();
  if (!s) return "";
  // Try a few common formats
  const direct = new Date(s);
  if (!isNaN(direct.getTime())) return direct.toISOString().slice(0, 10);
  const m = s.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})$/);
  if (m) {
    let [_, dd, mm, yy] = m as unknown as [string, string, string, string];
    if (yy.length === 2) yy = (parseInt(yy, 10) > 50 ? "19" : "20") + yy;
    const iso = `${yy.padStart(4, "0")}-${mm.padStart(2, "0")}-${dd.padStart(2, "0")}`;
    if (!isNaN(new Date(iso).getTime())) return iso;
  }
  return "";
}

function toNum(v: unknown): number {
  if (typeof v === "number" && Number.isFinite(v)) return v;
  if (typeof v === "string") {
    const cleaned = v.replace(/[$,\s]/g, "");
    if (cleaned === "") return 0;
    const n = parseFloat(cleaned);
    return Number.isFinite(n) ? n : 0;
  }
  return 0;
}

function detectGradeIdForSheet(sheetName: string, grades: FuelGrade[]): string | null {
  const n = sheetName.toLowerCase();
  for (const g of grades) {
    if (n.includes(g.id.toLowerCase())) return g.id;
    if (n.includes(g.label.toLowerCase())) return g.id;
  }
  // Fallback heuristics
  if (/reg|87/.test(n)) return grades.find((g) => g.id === "regular")?.id ?? null;
  if (/prem|91|93/.test(n)) return grades.find((g) => g.id === "premium")?.id ?? null;
  if (/diesel|ulsd/.test(n)) return grades.find((g) => g.id === "diesel")?.id ?? null;
  return null;
}

function findHeaderRow(matrix: unknown[][]): number {
  // Look at the first 10 rows; the header row is the one with the most
  // string cells that match any of our column hints.
  let bestIdx = 0;
  let bestScore = -1;
  for (let i = 0; i < Math.min(matrix.length, 10); i++) {
    const row = matrix[i] ?? [];
    let score = 0;
    for (const cell of row) {
      if (typeof cell !== "string") continue;
      for (const key of Object.keys(HEADER_HINTS) as Array<keyof typeof HEADER_HINTS>) {
        if (HEADER_HINTS[key].some((r) => r.test(cell))) {
          score += 1;
          break;
        }
      }
    }
    if (score > bestScore) {
      bestScore = score;
      bestIdx = i;
    }
  }
  return bestIdx;
}

export interface ParseOptions {
  /** Force-assign a sheet to a specific grade id, overriding auto-detection. */
  sheetGradeOverrides?: Record<string, string | null>;
  /** Fuel grades configured in the app. */
  grades: FuelGrade[];
}

export function parseWorkbook(buffer: ArrayBuffer, opts: ParseOptions): ImportPreview {
  const wb = XLSX.read(buffer, { cellDates: true, cellNF: false });
  const rows: ImportedDayRow[] = [];
  const sheetSummaries: ImportPreview["sheetSummaries"] = [];
  const warnings: string[] = [];

  for (const sheetName of wb.SheetNames) {
    const detected = opts.sheetGradeOverrides?.[sheetName] !== undefined
      ? opts.sheetGradeOverrides[sheetName]
      : detectGradeIdForSheet(sheetName, opts.grades);
    if (!detected) {
      sheetSummaries.push({
        sheetName,
        detectedGradeId: null,
        rowsParsed: 0,
        rowsSkipped: 0,
      });
      continue;
    }

    const ws = wb.Sheets[sheetName];
    const matrix = XLSX.utils.sheet_to_json<unknown[]>(ws, { header: 1, blankrows: false }) as unknown[][];
    if (matrix.length === 0) {
      sheetSummaries.push({ sheetName, detectedGradeId: detected, rowsParsed: 0, rowsSkipped: 0 });
      continue;
    }

    const headerIdx = findHeaderRow(matrix);
    const headers = (matrix[headerIdx] ?? []).map((h) => (h == null ? "" : String(h)));
    const colDate = pickColumn(headers, HEADER_HINTS.date);
    const colSales = pickColumn(headers, HEADER_HINTS.bullochSalesCAD);
    const colVolume = pickColumn(headers, HEADER_HINTS.bullochVolumeL);
    const colEod = pickColumn(headers, HEADER_HINTS.eodInventoryL);
    const colPurchase = pickColumn(headers, HEADER_HINTS.purchaseL);
    const colProductCost = pickColumn(headers, HEADER_HINTS.productCostExTaxPerL);
    const colDeliveryCost = pickColumn(headers, HEADER_HINTS.deliveryCostPerL);
    const colInvoice = pickColumn(headers, HEADER_HINTS.invoiceNo);

    if (colDate < 0 || (colSales < 0 && colVolume < 0)) {
      warnings.push(
        `Sheet "${sheetName}" -> ${detected}: could not find required date/sales/volume columns; skipped.`,
      );
      sheetSummaries.push({
        sheetName,
        detectedGradeId: detected,
        rowsParsed: 0,
        rowsSkipped: matrix.length - headerIdx - 1,
      });
      continue;
    }

    let parsed = 0;
    let skipped = 0;
    let firstDate: string | undefined;
    let lastDate: string | undefined;
    for (let r = headerIdx + 1; r < matrix.length; r++) {
      const row = matrix[r] ?? [];
      const date = toIso(row[colDate]);
      if (!date) {
        skipped += 1;
        continue;
      }
      const sales = colSales >= 0 ? toNum(row[colSales]) : 0;
      const volume = colVolume >= 0 ? toNum(row[colVolume]) : 0;
      const eod = colEod >= 0 ? toNum(row[colEod]) : undefined;
      const purchase = colPurchase >= 0 ? toNum(row[colPurchase]) : undefined;
      const cost = colProductCost >= 0 ? toNum(row[colProductCost]) : undefined;
      const deliv = colDeliveryCost >= 0 ? toNum(row[colDeliveryCost]) : undefined;
      const inv = colInvoice >= 0 ? String(row[colInvoice] ?? "").trim() : undefined;

      // Skip completely empty rows.
      if (sales === 0 && volume === 0 && !purchase && !eod) {
        skipped += 1;
        continue;
      }

      rows.push({
        date,
        gradeId: detected,
        bullochSalesCAD: sales,
        bullochVolumeL: volume,
        eodInventoryL: eod || undefined,
        purchaseL: purchase || undefined,
        productCostExTaxPerL: cost || undefined,
        deliveryCostPerL: deliv || undefined,
        invoiceNo: inv || undefined,
      });
      parsed += 1;
      if (!firstDate || date < firstDate) firstDate = date;
      if (!lastDate || date > lastDate) lastDate = date;
    }

    sheetSummaries.push({
      sheetName,
      detectedGradeId: detected,
      rowsParsed: parsed,
      rowsSkipped: skipped,
      firstDate,
      lastDate,
    });
  }

  return { rows, sheetSummaries, warnings };
}

/** Group ImportedDayRows by date for batch SalesFile writing. */
export function groupRowsByDate(rows: ImportedDayRow[]): Map<string, ImportedDayRow[]> {
  const m = new Map<string, ImportedDayRow[]>();
  for (const row of rows) {
    const existing = m.get(row.date) ?? [];
    existing.push(row);
    m.set(row.date, existing);
  }
  return m;
}
