import { useMemo, useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { Download, Loader2, Search, X } from "lucide-react";

import { api } from "@/lib/api";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { toCsv, type CsvColumn } from "@/lib/csv";
import { isoMonth } from "@/lib/utils";
import type { AuditEntry } from "@/lib/types";

const ALL = "all";

const CSV_COLUMNS: CsvColumn<AuditEntry>[] = [
  { header: "ts", value: (e) => e.ts },
  { header: "actor", value: (e) => e.actor },
  { header: "actorRole", value: (e) => e.actorRole },
  { header: "action", value: (e) => e.action },
  { header: "path", value: (e) => e.path },
  { header: "beforeSha", value: (e) => e.beforeSha },
  { header: "afterSha", value: (e) => e.afterSha },
  { header: "meta", value: (e) => (e.meta ? JSON.stringify(e.meta) : "") },
];

export default function AuditLogPage() {
  const [month, setMonth] = useState(isoMonth());
  const [actor, setActor] = useState(ALL);
  const [action, setAction] = useState(ALL);
  const [query, setQuery] = useState("");

  const q = useQuery({
    queryKey: ["audit", month],
    queryFn: () => api.audit(month),
  });

  const entries = useMemo(() => q.data?.entries ?? [], [q.data]);

  const actors = useMemo(
    () => [...new Set(entries.map((e) => e.actor))].sort(),
    [entries],
  );
  const actions = useMemo(
    () => [...new Set(entries.map((e) => e.action))].sort(),
    [entries],
  );

  const filtered = useMemo(() => {
    const needle = query.trim().toLowerCase();
    return entries.filter((e) => {
      if (actor !== ALL && e.actor !== actor) return false;
      if (action !== ALL && e.action !== action) return false;
      if (!needle) return true;
      const hay = `${e.path ?? ""} ${e.meta ? JSON.stringify(e.meta) : ""}`;
      return hay.toLowerCase().includes(needle);
    });
  }, [entries, actor, action, query]);

  const filtersActive = actor !== ALL || action !== ALL || query.trim() !== "";

  function clearFilters() {
    setActor(ALL);
    setAction(ALL);
    setQuery("");
  }

  function exportCsv() {
    const blob = new Blob([toCsv(filtered, CSV_COLUMNS)], {
      type: "text/csv;charset=utf-8",
    });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `mkrgas-audit-${month}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  }

  return (
    <div className="space-y-6">
      <header className="flex flex-wrap items-end justify-between gap-4">
        <div>
          <h1 className="text-3xl font-semibold tracking-tight">Audit log</h1>
          <p className="text-sm text-muted-foreground">
            Every write, login attempt, and admin action is recorded here.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Label className="text-xs text-muted-foreground">Month</Label>
          <Input
            type="month"
            value={month}
            onChange={(e) => setMonth(e.target.value)}
            className="w-44"
          />
        </div>
      </header>

      <Card>
        <CardHeader className="gap-3 space-y-0">
          <div className="flex flex-wrap items-start justify-between gap-3">
            <div className="space-y-1.5">
              <CardTitle>Entries</CardTitle>
              <CardDescription>
                {filtered.length} of {entries.length} entries
              </CardDescription>
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={exportCsv}
              disabled={filtered.length === 0}
            >
              <Download /> Export CSV
            </Button>
          </div>

          <div className="flex flex-wrap items-center gap-2">
            <div className="relative">
              <Search className="pointer-events-none absolute left-2.5 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
              <Input
                type="search"
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder="Search path or details"
                aria-label="Search audit entries"
                className="h-8 w-60 pl-8 text-xs"
              />
            </div>
            <Select value={actor} onValueChange={setActor}>
              <SelectTrigger className="h-8 w-40 text-xs" aria-label="Filter by actor">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value={ALL}>All actors</SelectItem>
                {actors.map((a) => (
                  <SelectItem key={a} value={a}>
                    @{a}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Select value={action} onValueChange={setAction}>
              <SelectTrigger className="h-8 w-40 text-xs" aria-label="Filter by action">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value={ALL}>All actions</SelectItem>
                {actions.map((a) => (
                  <SelectItem key={a} value={a}>
                    {a}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            {filtersActive ? (
              <Button variant="ghost" size="sm" onClick={clearFilters}>
                <X /> Clear
              </Button>
            ) : null}
          </div>
        </CardHeader>
        <CardContent>
          {q.isLoading ? (
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <Loader2 className="h-4 w-4 animate-spin" /> Loading…
            </div>
          ) : null}
          {entries.length === 0 ? (
            <div className="rounded-md border border-dashed py-10 text-center text-sm text-muted-foreground">
              No audit entries yet for {month}.
            </div>
          ) : filtered.length === 0 ? (
            <div className="rounded-md border border-dashed py-10 text-center text-sm text-muted-foreground">
              No entries match these filters.{" "}
              <button
                type="button"
                onClick={clearFilters}
                className="underline underline-offset-4"
              >
                Clear filters
              </button>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead className="text-xs uppercase text-muted-foreground">
                  <tr>
                    <th className="px-2 py-2 text-left">Time (UTC)</th>
                    <th className="px-2 py-2 text-left">Actor</th>
                    <th className="px-2 py-2 text-left">Action</th>
                    <th className="px-2 py-2 text-left">Path</th>
                  </tr>
                </thead>
                <tbody>
                  {filtered
                    .slice()
                    .reverse()
                    .map((e, i) => (
                      <tr key={i} className="border-t">
                        <td className="px-2 py-2 number-tabular text-xs">
                          {e.ts.replace("T", " ").slice(0, 19)}
                        </td>
                        <td className="px-2 py-2">
                          <Badge variant="outline" className="mr-2 capitalize">
                            {e.actorRole}
                          </Badge>
                          @{e.actor}
                        </td>
                        <td className="px-2 py-2">
                          <Badge
                            variant={
                              e.action === "login-failed"
                                ? "destructive"
                                : e.action === "login"
                                  ? "success"
                                  : "secondary"
                            }
                          >
                            {e.action}
                          </Badge>
                        </td>
                        <td className="px-2 py-2 font-mono text-xs">{e.path ?? "--"}</td>
                      </tr>
                    ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}
