/**
 * Helper that computes the derived/margin/YYYY-MM-DD.json snapshot from the
 * day's sales + delivery data + previous day's margin (for rolling-avg cost),
 * then persists it. Lives here so both the EOD and the Fuel Delivery flows can
 * call it after their primary writes.
 */
import { api } from "@/lib/api";
import {
  computeDailyMargin,
  type DailyInputs,
  type GradeState,
  ZERO_TAX_CONFIG,
  type TaxConfig,
} from "@/lib/math/cost";
import type {
  DerivedMarginFile,
  DerivedMarginRow,
  FuelDeliveriesFile,
  FuelGradesConfig,
  SalesFile,
  TaxConstants,
} from "@/lib/types";

function previousIsoDate(date: string): string {
  const d = new Date(`${date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() - 1);
  return d.toISOString().slice(0, 10);
}

async function loadPreviousState(
  date: string,
  gradesCfg: FuelGradesConfig,
): Promise<Map<string, GradeState>> {
  const state = new Map<string, GradeState>();
  for (const g of gradesCfg.grades) {
    state.set(g.id, {
      inventoryL: gradesCfg.openingInventoryL?.[g.id] ?? 0,
      rollingAvgCost: gradesCfg.openingRollingAvgCost?.[g.id] ?? 0,
    });
  }
  // Walk back up to 7 days to seed state if a snapshot exists.
  for (let i = 0; i < 7; i++) {
    const probe = previousIsoDate(
      i === 0 ? date : new Date(new Date(date).getTime() - i * 86_400_000).toISOString().slice(0, 10),
    );
    try {
      const res = await api.readData<DerivedMarginFile>(`derived/margin/${probe}.json`);
      if (res.exists && res.data) {
        for (const row of res.data.rows) {
          state.set(row.gradeId, {
            inventoryL: row.eodInventoryL,
            rollingAvgCost: row.rollingAvgCost,
          });
        }
        return state;
      }
    } catch {
      // ignore -- treat as no prior snapshot
    }
  }
  return state;
}

function toTaxConfig(t: TaxConstants | undefined): TaxConfig {
  if (!t) return ZERO_TAX_CONFIG;
  return {
    fetPerL: t.fetPerL,
    pftPerL: t.pftPerL,
    carbonPerL: t.carbonPerL,
    urbanPerL: t.urbanPerL,
    rebatePerL: t.rebatePerL,
    gstPct: t.gstPct,
    pstPct: t.pstPct,
    hstPct: t.hstPct,
  };
}

export interface RecomputeArgs {
  date: string;
  gradesCfg: FuelGradesConfig;
  taxes: TaxConstants;
  sales: SalesFile | null;
  delivery: FuelDeliveriesFile | null;
}

export async function recomputeAndSaveMargin(args: RecomputeArgs): Promise<DerivedMarginFile> {
  const { date, gradesCfg, taxes, sales, delivery } = args;
  const taxCfg = toTaxConfig(taxes);
  const prev = await loadPreviousState(date, gradesCfg);

  const rows: DerivedMarginRow[] = gradesCfg.grades.map((grade) => {
    const prevState = prev.get(grade.id) ?? { inventoryL: 0, rollingAvgCost: 0 };
    const deliveryAgg = (delivery?.entries ?? [])
      .filter((e) => e.gradeId === grade.id)
      .reduce(
        (acc, e) => {
          const totalL = acc.purchaseL + e.purchaseVolumeL;
          if (totalL <= 0) return acc;
          const weightedCost =
            (acc.purchaseL * acc.unitCost +
              e.purchaseVolumeL * (e.productCostExTaxPerL + e.deliveryCostPerL)) /
            totalL;
          return {
            purchaseL: totalL,
            unitCost: weightedCost,
            deliveryCost: 0,
          };
        },
        { purchaseL: 0, unitCost: 0, deliveryCost: 0 },
      );

    const fuelSales = sales?.fuel.find((f) => f.gradeId === grade.id);
    const inputs: DailyInputs = {
      purchaseL: deliveryAgg.purchaseL || undefined,
      productCostExTaxPerL: deliveryAgg.purchaseL > 0 ? deliveryAgg.unitCost : undefined,
      deliveryCostPerL: 0,
      bullochSalesCAD: fuelSales?.bullochSalesCAD,
      bullochVolumeL: fuelSales?.bullochVolumeL,
    };
    const { metrics } = computeDailyMargin(prevState, inputs, taxCfg);

    return {
      gradeId: grade.id,
      productCostInclDelivery: metrics.productCostInclDelivery,
      rollingAvgCost: metrics.rollingAvgCost,
      eodInventoryL: fuelSales?.eodInventoryL ?? metrics.eodInventoryL,
      avgPumpPrice: metrics.avgPumpPrice,
      netSellPrice: metrics.netSellPrice,
      associateMargin: metrics.associateMargin,
      grossProfit: metrics.grossProfit,
      bullochVolumeL: fuelSales?.bullochVolumeL ?? 0,
      bullochSalesCAD: fuelSales?.bullochSalesCAD ?? 0,
      hasSales: metrics.hasSales,
      hasDelivery: metrics.hasDelivery,
    };
  });

  const derived: DerivedMarginFile = { date, rows };
  const existing = await api.readData<DerivedMarginFile>(`derived/margin/${date}.json`);
  await api.writeData(
    `derived/margin/${date}.json`,
    derived,
    existing.sha ?? null,
    `derived margin: ${date}`,
  );
  return derived;
}
