import { useQueries, useQuery, useQueryClient } from "@tanstack/react-query";
import { useMemo, useState } from "react";
import {
  ArrowDownRight,
  ArrowUpRight,
  Droplets,
  Fuel,
  Loader2,
  Pin,
  Plus,
  TrendingUp,
  Trash2,
  Wallet,
} from "lucide-react";
