import { useEffect, type ReactNode } from "react";
import { Navigate, Route, Routes } from "react-router-dom";

import { useAuth } from "@/lib/auth-store";
import { ErrorBoundary } from "@/components/ErrorBoundary";
import { AppLayout } from "@/app/AppLayout";
import { ProtectedRoute } from "@/app/ProtectedRoute";
import LoginPage from "@/features/auth/LoginPage";
import ChangePasswordPage from "@/features/auth/ChangePasswordPage";
import DashboardPage from "@/features/dashboard/DashboardPage";
import EmployeeDashboard from "@/features/dashboard/EmployeeDashboard";
import EodReportPage from "@/features/sales/EodReportPage";
import SalesPage from "@/features/sales/SalesPage";
import FuelPage from "@/features/fuel/FuelPage";
import FuelDeliveryPage from "@/features/fuel/FuelDeliveryPage";
import SchedulePage from "@/features/schedule/SchedulePage";
import ExpensesPage from "@/features/expenses/ExpensesPage";
import ReportsPage from "@/features/reports/ReportsPage";
import EmployeesPage from "@/features/employees/EmployeesPage";
import AuditLogPage from "@/features/audit/AuditLogPage";
import SettingsPage from "@/features/settings/SettingsPage";

/** Admins get the profit dashboard; employees get the operations hub.
    Split at the route so the profit page (and its derived/ queries) never
    mounts for an employee. */
function RoleDashboard() {
  const user = useAuth((s) => s.user);
  return user?.role === "admin" ? <DashboardPage /> : <EmployeeDashboard />;
}

/** Per-route boundary: one page throwing keeps the shell, nav and sidebar alive.
    Each route mounts its own instance, so navigating away clears the error. */
const guarded = (el: ReactNode) => <ErrorBoundary>{el}</ErrorBoundary>;

export default function App() {
  const initialize = useAuth((s) => s.initialize);
  const initialized = useAuth((s) => s.initialized);
  useEffect(() => {
    initialize();
  }, [initialize]);

  if (!initialized) {
    return (
      <div className="flex h-full items-center justify-center text-muted-foreground">
        Loading…
      </div>
    );
  }

  return (
    <Routes>
      <Route path="/login" element={<LoginPage />} />
      <Route
        path="/change-password"
        element={
          <ProtectedRoute>
            <ChangePasswordPage />
          </ProtectedRoute>
        }
      />
      <Route
        path="/"
        element={
          <ProtectedRoute>
            <AppLayout />
          </ProtectedRoute>
        }
      >
        <Route index element={<Navigate to="/dashboard" replace />} />
        <Route path="dashboard" element={guarded(<RoleDashboard />)} />
        <Route path="sales" element={guarded(<SalesPage />)} />
        <Route path="eod" element={guarded(<EodReportPage />)} />
        <Route path="fuel" element={guarded(<FuelPage />)} />
        <Route path="fuel/delivery" element={guarded(<FuelDeliveryPage />)} />
        <Route path="schedule" element={guarded(<SchedulePage />)} />
        <Route path="expenses" element={guarded(<ExpensesPage />)} />
        <Route path="reports" element={guarded(<ReportsPage />)} />
        <Route path="employees" element={guarded(<EmployeesPage />)} />
        <Route path="audit" element={guarded(<AuditLogPage />)} />
        <Route path="settings" element={guarded(<SettingsPage />)} />
        <Route path="*" element={<Navigate to="/dashboard" replace />} />
      </Route>
    </Routes>
  );
}
