/**
 * Cash drawer reconciliation widget.
 *
 * Provides a denomination keypad so the cashier can count the drawer in
 * about thirty seconds, then shows the running total and a short/over
 * indicator against the expected cash amount derived from the day's
 * revenue minus card tenders minus float and deposit.
 */
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { formatCAD } from "@/lib/utils";
import type { CashCount } from "@/lib/types";

export const EMPTY_CASH_COUNT: CashCount = {
  hundreds: 0,
  fifties: 0,
  twenties: 0,
  tens: 0,
  fives: 0,
  toonies: 0,
  loonies: 0,
  quarters: 0,
  dimes: 0,
  nickels: 0,
  pennies: 0,
  chequesCAD: 0,
};

const DENOMS: Array<{ key: keyof CashCount; label: string; face: number; isAmount?: boolean }> = [
  { key: "hundreds", label: "$100", face: 100 },
  { key: "fifties", label: "$50", face: 50 },
  { key: "twenties", label: "$20", face: 20 },
  { key: "tens", label: "$10", face: 10 },
  { key: "fives", label: "$5", face: 5 },
  { key: "toonies", label: "$2", face: 2 },
  { key: "loonies", label: "$1", face: 1 },
  { key: "quarters", label: "25¢", face: 0.25 },
  { key: "dimes", label: "10¢", face: 0.1 },
  { key: "nickels", label: "5¢", face: 0.05 },
  { key: "pennies", label: "1¢", face: 0.01 },
  { key: "chequesCAD", label: "Cheques $", face: 1, isAmount: true },
];

export function totalCashCount(count: CashCount): number {
  let total = 0;
  for (const d of DENOMS) {
    const v = count[d.key] || 0;
    total += d.isAmount ? v : v * d.face;
  }
  return total;
}

interface CashDrawerProps {
  value: CashCount | undefined;
  expectedCAD: number;
  onChange: (next: CashCount) => void;
}

export function CashDrawer({ value, expectedCAD, onChange }: CashDrawerProps) {
  const count = value ?? EMPTY_CASH_COUNT;
  const total = totalCashCount(count);
  const variance = total - expectedCAD;
  const varianceLabel = variance === 0 ? "Balanced" : variance > 0 ? "Over" : "Short";
  const varianceColor =
    Math.abs(variance) < 0.5
      ? "text-emerald-600 dark:text-emerald-400"
      : Math.abs(variance) < 5
        ? "text-amber-600 dark:text-amber-400"
        : "text-rose-600 dark:text-rose-400";

  function update(key: keyof CashCount, raw: string) {
    const num = parseFloat(raw);
    onChange({ ...count, [key]: Number.isFinite(num) ? num : 0 });
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle>Cash drawer count</CardTitle>
        <CardDescription>
          Count each denomination after close. The variance vs expected cash highlights short / over.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="grid grid-cols-3 gap-3 md:grid-cols-6">
          {DENOMS.map((d) => {
            const v = count[d.key] || 0;
            const subtotal = d.isAmount ? v : v * d.face;
            return (
              <div key={d.key} className="space-y-1">
                <Label className="text-xs text-muted-foreground">
                  {d.label}
                  {!d.isAmount ? ` x` : ""}
                </Label>
                <Input
                  type="number"
                  step={d.isAmount ? "0.01" : "1"}
                  min={0}
                  inputMode={d.isAmount ? "decimal" : "numeric"}
                  value={v === 0 ? "" : v}
                  onChange={(e) => update(d.key, e.target.value)}
                  placeholder="0"
                />
                <div className="text-[10px] text-muted-foreground number-tabular">
                  = {formatCAD(subtotal)}
                </div>
              </div>
            );
          })}
        </div>
        <div className="grid grid-cols-3 gap-3 rounded-md border bg-card/50 p-3 text-sm">
          <Stat label="Counted total" value={formatCAD(total)} />
          <Stat label="Expected cash" value={formatCAD(expectedCAD)} />
          <Stat
            label={varianceLabel}
            value={`${variance >= 0 ? "+" : ""}${formatCAD(variance)}`}
            valueClassName={varianceColor}
          />
        </div>
      </CardContent>
    </Card>
  );
}

function Stat({
  label,
  value,
  valueClassName,
}: {
  label: string;
  value: string;
  valueClassName?: string;
}) {
  return (
    <div>
      <div className="text-xs uppercase tracking-wide text-muted-foreground">{label}</div>
      <div className={`number-tabular text-base font-semibold ${valueClassName ?? ""}`}>
        {value}
      </div>
    </div>
  );
}
