import { useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { Loader2, Save, Trash2, UserCheck, UserMinus, UserPlus } from "lucide-react";

import { api } from "@/lib/api";
import { useAuth } from "@/lib/auth-store";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";

interface AdminUser {
  id: string;
  username: string;
  displayName: string;
  role: "admin" | "employee";
  active: boolean;
  createdAt: string;
}

function sameUser(a: string, b: string) {
  return a.trim().toLowerCase() === b.trim().toLowerCase();
}

export default function EmployeesPage() {
  const qc = useQueryClient();
  const currentUsername = useAuth((s) => s.user?.username ?? "");
  const q = useQuery({
    queryKey: ["admin", "users"],
    queryFn: () => api.listUsers(),
  });
  const [form, setForm] = useState({
    username: "",
    displayName: "",
    role: "employee" as "admin" | "employee",
    password: "",
  });
  const [submitting, setSubmitting] = useState(false);
  const [rowBusy, setRowBusy] = useState<string | null>(null);

  async function createUser(e: React.FormEvent) {
    e.preventDefault();
    setSubmitting(true);
    try {
      await api.upsertUser({ ...form, mustChangePassword: true });
      toast.success("User created");
      setForm({ username: "", displayName: "", role: "employee", password: "" });
      qc.invalidateQueries({ queryKey: ["admin", "users"] });
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed");
    } finally {
      setSubmitting(false);
    }
  }

  async function deactivate(username: string) {
    if (!confirm(`Temporarily deactivate @${username}? They will not be able to sign in until reactivated.`))
      return;
    setRowBusy(`deactivate:${username}`);
    try {
      await api.deactivateUser(username);
      toast.success("User deactivated");
      qc.invalidateQueries({ queryKey: ["admin", "users"] });
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed");
    } finally {
      setRowBusy(null);
    }
  }

  async function reactivate(user: AdminUser) {
    setRowBusy(`reactivate:${user.id}`);
    try {
      await api.upsertUser({
        id: user.id,
        username: user.username,
        displayName: user.displayName,
        role: user.role,
        active: true,
      });
      toast.success("User reactivated");
      qc.invalidateQueries({ queryKey: ["admin", "users"] });
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed");
    } finally {
      setRowBusy(null);
    }
  }

  async function changeRole(user: AdminUser, role: "admin" | "employee") {
    if (user.role === role) return;
    setRowBusy(`role:${user.id}`);
    try {
      await api.upsertUser({
        id: user.id,
        username: user.username,
        displayName: user.displayName,
        role,
        active: user.active,
      });
      toast.success("Role updated");
      qc.invalidateQueries({ queryKey: ["admin", "users"] });
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed");
    } finally {
      setRowBusy(null);
    }
  }

  async function deletePermanently(user: AdminUser) {
    if (sameUser(user.username, currentUsername)) {
      toast.error("You cannot delete your own account from this screen.");
      return;
    }
    const phrase = prompt(
      `Permanently delete @${user.username}? This removes the account from the system.\n\nType the username exactly to confirm:`,
    );
    if (phrase === null) return;
    if (phrase !== user.username) {
      toast.error("Username did not match; nothing was deleted.");
      return;
    }
    setRowBusy(`delete:${user.id}`);
    try {
      await api.deleteUserPermanently(user.username);
      toast.success("User removed");
      qc.invalidateQueries({ queryKey: ["admin", "users"] });
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed");
    } finally {
      setRowBusy(null);
    }
  }

  async function resetPassword(user: AdminUser) {
    const password = prompt(`Set a new password for ${user.username}`);
    if (!password) return;
    try {
      await api.upsertUser({
        id: user.id,
        username: user.username,
        displayName: user.displayName,
        role: user.role,
        active: user.active,
        password,
        mustChangePassword: true,
      });
      toast.success("Password reset");
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Failed");
    }
  }

  return (
    <div className="space-y-6">
      <header>
        <h1 className="text-3xl font-semibold tracking-tight">Employees</h1>
        <p className="text-sm text-muted-foreground">
          Add accounts, change roles, deactivate or reactivate access, reset passwords, or remove users
          entirely.
        </p>
      </header>

      <Card>
        <CardHeader>
          <CardTitle>Add user</CardTitle>
          <CardDescription>
            New users must change their password on first login.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={createUser} className="grid gap-3 md:grid-cols-5">
            <div className="space-y-1.5">
              <Label className="text-xs text-muted-foreground">Username</Label>
              <Input
                value={form.username}
                onChange={(e) => setForm({ ...form, username: e.target.value })}
                required
              />
            </div>
            <div className="space-y-1.5">
              <Label className="text-xs text-muted-foreground">Display name</Label>
              <Input
                value={form.displayName}
                onChange={(e) => setForm({ ...form, displayName: e.target.value })}
                required
              />
            </div>
            <div className="space-y-1.5">
              <Label className="text-xs text-muted-foreground">Role</Label>
              <Select
                value={form.role}
                onValueChange={(v: "admin" | "employee") => setForm({ ...form, role: v })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="employee">Employee</SelectItem>
                  <SelectItem value="admin">Admin</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <Label className="text-xs text-muted-foreground">Initial password</Label>
              <Input
                type="password"
                value={form.password}
                onChange={(e) => setForm({ ...form, password: e.target.value })}
                required
                minLength={8}
              />
            </div>
            <div className="flex items-end">
              <Button type="submit" disabled={submitting} className="w-full">
                {submitting ? <Loader2 className="h-4 w-4 animate-spin" /> : <UserPlus className="h-4 w-4" />}
                Add user
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>All users</CardTitle>
        </CardHeader>
        <CardContent>
          {q.isLoading ? (
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <Loader2 className="h-4 w-4 animate-spin" /> Loading…
            </div>
          ) : null}
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="text-xs uppercase text-muted-foreground">
                <tr>
                  <th className="px-2 py-2 text-left">Username</th>
                  <th className="px-2 py-2 text-left">Display name</th>
                  <th className="px-2 py-2 text-left">Role</th>
                  <th className="px-2 py-2 text-left">Status</th>
                  <th className="px-2 py-2"></th>
                </tr>
              </thead>
              <tbody>
                {(q.data?.users ?? []).map((u) => (
                  <tr key={u.id} className="border-t">
                    <td className="px-2 py-2 font-medium">@{u.username}</td>
                    <td className="px-2 py-2">{u.displayName}</td>
                    <td className="px-2 py-2">
                      <Select
                        value={u.role}
                        disabled={rowBusy !== null}
                        onValueChange={(v: "admin" | "employee") =>
                          changeRole(u as AdminUser, v)
                        }
                      >
                        <SelectTrigger className="h-8 w-[8.5rem] capitalize">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="employee">Employee</SelectItem>
                          <SelectItem value="admin">Admin</SelectItem>
                        </SelectContent>
                      </Select>
                    </td>
                    <td className="px-2 py-2">
                      {u.active ? (
                        <Badge variant="success">Active</Badge>
                      ) : (
                        <Badge variant="destructive">Disabled</Badge>
                      )}
                    </td>
                    <td className="space-x-2 px-2 py-2 text-right whitespace-nowrap">
                      <Button
                        size="sm"
                        variant="outline"
                        disabled={rowBusy !== null}
                        onClick={() => resetPassword(u as AdminUser)}
                      >
                        <Save className="h-4 w-4" /> Reset password
                      </Button>
                      {u.active ? (
                        <Button
                          size="sm"
                          variant="ghost"
                          disabled={
                            rowBusy !== null || sameUser(u.username, currentUsername)
                          }
                          onClick={() => deactivate(u.username)}
                        >
                          <UserMinus className="h-4 w-4" /> Deactivate
                        </Button>
                      ) : (
                        <Button
                          size="sm"
                          variant="ghost"
                          disabled={rowBusy !== null}
                          onClick={() => reactivate(u as AdminUser)}
                        >
                          <UserCheck className="h-4 w-4" /> Reactivate
                        </Button>
                      )}
                      <Button
                        size="sm"
                        variant="destructive"
                        disabled={
                          rowBusy !== null || sameUser(u.username, currentUsername)
                        }
                        onClick={() => deletePermanently(u as AdminUser)}
                      >
                        <Trash2 className="h-4 w-4" /> Delete
                      </Button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}
