/**
 * Store location picker. Coordinates drive competitor discovery (which
 * stations count as "nearby") and the distance shown against each one.
 *
 * Deliberately API-free: you paste what Google Maps' right-click menu gives
 * you, or a map URL, and it parses. No Geocoding key needed, and it works
 * before any Maps API is configured.
 */
import { useState } from "react";
import { Check, MapPin, X } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { parseLatLng } from "@/lib/latlng";
import type { StoreLocation } from "@/lib/types";

interface Props {
  location: StoreLocation | undefined;
  radiusKm: number;
  onLocation: (loc: StoreLocation | undefined) => void;
  onRadius: (km: number) => void;
}

export function StoreLocationField({ location, radiusKm, onLocation, onRadius }: Props) {
  const [paste, setPaste] = useState("");
  const [error, setError] = useState<string | null>(null);

  function apply() {
    const parsed = parseLatLng(paste);
    if (!parsed) {
      setError("Couldn't read coordinates from that. Expected something like 43.653226, -79.383184");
      return;
    }
    setError(null);
    setPaste("");
    onLocation({
      lat: parsed.lat,
      lng: parsed.lng,
      source: "manual",
      setAt: new Date().toISOString(),
    });
  }

  return (
    <div className="space-y-3 rounded-lg border border-border/60 bg-background/30 p-4">
      <div className="flex items-center gap-2">
        <MapPin className="h-4 w-4 text-primary" />
        <Label className="text-sm font-medium">Station location</Label>
      </div>

      {location ? (
        <div className="flex flex-wrap items-center gap-3">
          <span className="number-tabular rounded-md bg-secondary px-2.5 py-1 text-sm">
            {location.lat.toFixed(6)}, {location.lng.toFixed(6)}
          </span>
          <a
            href={`https://www.google.com/maps/search/?api=1&query=${location.lat},${location.lng}`}
            target="_blank"
            rel="noopener noreferrer"
            className="text-xs text-muted-foreground underline hover:text-foreground"
          >
            Verify on map
          </a>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => onLocation(undefined)}
            className="ml-auto text-muted-foreground"
          >
            <X className="h-3.5 w-3.5" /> Clear
          </Button>
        </div>
      ) : (
        <p className="text-xs text-muted-foreground">
          Not set — competitor tracking stays off until the station has coordinates.
        </p>
      )}

      <div className="space-y-1.5">
        <div className="flex gap-2">
          <Input
            value={paste}
            onChange={(e) => {
              setPaste(e.target.value);
              setError(null);
            }}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault();
                apply();
              }
            }}
            placeholder="43.653226, -79.383184  — or paste a Google Maps link"
            className="flex-1"
          />
          <Button variant="outline" onClick={apply} disabled={!paste.trim()}>
            <Check className="h-4 w-4" /> Set
          </Button>
        </div>
        {error ? (
          <p className="text-xs font-medium text-red-600 dark:text-red-400" role="alert">
            {error}
          </p>
        ) : (
          <p className="text-xs text-muted-foreground">
            In Google Maps, right-click your station → click the coordinates at the top of the menu
            to copy them, then paste here.
          </p>
        )}
      </div>

      <div className="flex items-center gap-3 border-t border-border/60 pt-3">
        <Label htmlFor="radius" className="text-xs text-muted-foreground">
          Search competitors within
        </Label>
        <Input
          id="radius"
          type="number"
          min={1}
          max={25}
          step={1}
          value={radiusKm}
          onChange={(e) => onRadius(Math.min(25, Math.max(1, Number(e.target.value) || 5)))}
          className="w-20"
        />
        <span className="text-xs text-muted-foreground">km</span>
      </div>
    </div>
  );
}
